<template>
  <div class="sendBag">
    <div class="content">
      <!-- <div class="title">拼手气红包</div> -->
      <van-popover
        v-model="showPopover"
        trigger="click"
        :actions="actions"
        @select="onSelect"
      >
        <template #reference>
          <div class="title">{{ title }}<van-icon name="arrow-down" /></div>
        </template>
      </van-popover>
    </div>
    <van-form @submit="onSubmit">
      <van-field
        v-if="showBagNum"
        v-model="bagNum"
        name="红包个数"
        placeholder="填写红包个数"
        input-align="right"
        type="digit"
        autocomplete="off"
      >
        <div slot="label" style="display:flex">

          <div class="redBag" />
          <span class="filed-label">红包个数</span>
        </div>
        <template slot="button">个</template>
      </van-field>
      <van-field
        v-if="!showBagNum"
        v-model="recipient"
        name="发给谁"
        placeholder=""
        input-align="right"
        type=""
        autocomplete="off"
        right-icon="arrow"
        readonly
        @click="goList()"
      >
        <div
          slot="label"
          style="display:flex"
          @selectedName="selectedNameChange"
        >
          <span class="filed-label">发给谁</span>
        </div>
      </van-field>
      <div class="peopleNum">本群共{{ peopleNum }}人；余额:{{ remainingSum }}U<span style="font-weight:600;margin-left:10px;color:#20BB3C;cursor:pointer" @click="toTelRecharge()">立即充值</span></div>
      <van-field
        v-model="totalAmount"
        name="总金额"
        placeholder="$0.00"
        input-align="right"
        type="number"
        autocomplete="off"
      >
        <div slot="label" style="display:flex">
          <div class="usdt-icon" />
          <span class="filed-label">{{ totalAmountName }}</span>
        </div>
      </van-field>
      <van-field
        v-model="bless"
        name="祝福语"
        placeholder="恭喜发财，大吉大利"
        input-align="right"
        autocomplete="off"
      >
        <template slot="right-icon" />
      </van-field>
      <van-field name="uploader" label="选择红包封面">
        <template #input>
          <van-uploader v-model="uploader" :preview-full-image="false" :after-read="afterRead" :max-count="2" @click-preview="clickPreview" />
        </template>
      </van-field>
      <van-field v-if="showBagNum" name="checkbox" label="是否匿名" label-width="65px">
        <template #input>
          <van-checkbox v-model="isNameLess" shape="square" style="margin-right:35px" />
          <!-- <van-radio-group v-model="sex" direction="horizontal">
            <van-radio name="1">女孩</van-radio>
            <van-radio name="2">男孩</van-radio>
            <van-radio name="3">全部</van-radio>
          </van-radio-group> -->
          <div class="sexTab">
            <div v-for="(item,index) in sexTabList" :key="index" :class="tagColor === index?'tab-click':'tab'" @click="onChoose(index)">{{ item.title }}</div>
          </div>
        </template>
      </van-field>
      <div class="money">
        <div>{{ (title==='普通红包'?totalAmount*bagNum:totalAmount) || 0.00 }}</div>
        <span>USDT</span>
      </div>
      <div style="margin:auto;width:100%;dispaly:block">
        <van-button class="button" color="#F24530" size="normal" block type="info" native-type="submit" :disabled="disabled" @click="saveRedpack()">{{ buttonText }}</van-button>
      </div>
      <div class="tips">{{ tips }}</div>
    </van-form>

  </div>
</template>
<script>
// import TitleLine from '../modules/TitleLine'
// import { redpackimg, fileUpload } from '@/api/upload'
export default {
  components: {
    // TitleLine
  },
  data() {
    return {
      remainingSum: '100', // 余额
      recipient: '',
      showBagNum: true,
      title: '拼手气红包',
      bagNum: '',
      totalAmount: '',
      totalAmountName: '总金额',
      bless: '',
      uploader: [{ url: 'http://img.rr888.vip/img/yl-hbmrtb.png', deletable: false }],
      // uploader: [],
      isNameLess: false,
      sex: '',
      peopleNum: '12',
      money: '0.00',
      tips: '未领取的红包，将于24小时后发起退款',
      showPopover: false,
      // 通过 actions 属性来定义菜单选项
      actions: [{ text: '拼手气红包', type: '2' }, { text: '普通红包', type: '1' }, { text: '专属红包', type: '3' }, { text: '任务红包', type: '4' }],
      tagColor: 0,
      sexTabList: [{ title: '只限女孩' }, { title: '只限男孩' }, { title: '全部' }],
      userid: null,
      chatid: null,
      params: { type: '2' },
      buttonText: '塞钱进钱包',
      disabled: false
    }
  },
  mounted() {
    if (this.$route.query.uname) {
      this.recipient = this.$route.query.uname
      this.totalAmountName = '金额'
      this.showBagNum = false
      this.params.type = '3'
      this.title = '专属红包'
    }
    if (this.$route.query.test) {
      const formData = new FormData()
      formData.append('initData', 'user=%7B%22id%22%3A6669226098%2C%22first_name%22%3A%22%E4%BB%B2%E6%98%8E%22%2C%22last_name%22%3A%22%E7%8E%8B%22%2C%22username%22%3A%22wangzhongming%22%2C%22language_code%22%3A%22zh-hans%22%2C%22allows_write_to_pm%22%3Atrue%7D&chat_instance=-594754764806165235&chat_type=supergroup&auth_date=1701666073&hash=767614987aca682c959542d539351ed7c7d6c95de45b2355a4444e428461d842')
      formData.append('hash', '767614987aca682c959542d539351ed7c7d6c95de45b2355a4444e428461d842')
      fetch(process.env.VUE_APP_BASE_API + '/yule/checkInitData', {
        method: 'POST',
        body: formData
      }).then(res => res.json())
        .then(data => {
          console.log(data)
          this.initData(data)
        })
    } else {
      const script = document.createElement('script')
      script.type = 'text/javascript'
      script.src = 'https://telegram.org/js/telegram-web-app.js?1'
      document.body.appendChild(script)
      script.onload = () => {
        const formData = new FormData()
        formData.append('initData', Telegram.WebApp.initData)
        formData.append('hash', Telegram.WebApp.initDataUnsafe.hash)
        fetch(process.env.VUE_APP_BASE_API + '/yule/checkInitData', {
          method: 'POST',
          body: formData
        }).then(res => res.json())
          .then(data => {
            console.log(data)
            this.initData(data)
          })
      }
    }
  },
  methods: {
    initData(data) {
      this.userid = data.userid
      this.chatid = data.chatid
      this.remainingSum = data.moneys
      this.peopleNum = data.membersize
      if (!this.$route.query.type || this.$route.query.type === data.lastrecord.type) {
        this.clickPreview(this.uploader[0], data.lastrecord.medialink)
        this.totalAmount = data.lastrecord.moneys || ''
        this.bless = data.lastrecord.remark || ''
        this.bagNum = data.lastrecord.nums || ''
        this.isNameLess = data.lastrecord.anonymous
        this.onSelect({ type: this.$route.query.type ? this.$route.query.type : data.lastrecord.type })
      }
    },
    // updateList(chatid) {
    //   fetch(process.env.VUE_APP_BASE_API + '/yule/getGroupUsers?chatid=' + chatid + '&suid=' + this.$route.query.suid + '&username=', {
    //     method: 'POST'
    //   }).then(res => res.json())
    //     .then(data => {
    //       this.peopleNum = data.size
    //     })
    // },
    toTelRecharge() {
      this.$router.push({ path: '/telRecharge', query: { userid: this.userid, chatid: this.chatid }})
    },
    clickPreview(file, url) {
      let ele
      if (file.deletable === false) {
        ele = document.getElementsByClassName('van-uploader__preview')[0]
        if (document.getElementsByClassName('van-uploader__preview')[1]) {
          document.getElementsByClassName('van-uploader__preview')[1].style.border = 'none'
        }
      } else {
        ele = document.getElementsByClassName('van-uploader__preview')[1]
        document.getElementsByClassName('van-uploader__preview')[0].style.border = 'none'
      }
      // const ele = document.getElementsByClassName('van-uploader__preview')[0]
      ele.style.border = '1px solid #07c160'

      this.params.medialink = file.url || url
    },
    saveRedpack() {
      let totalAmountSum // 总发包金额
      totalAmountSum = this.title === '普通红包' ? this.totalAmount * this.bagNum : this.totalAmount
      if (this.bagNum > this.peopleNum) {
        this.$toast('红包数量应不大于群人数！')
        return false
      }
      if (this.remainingSum < totalAmountSum) {
        this.$dialog.confirm({
          title: '提示',
          message: '余额少于发包金额，是否跳转到充值页面？'
        })
          .then(() => {
            this.$router.push({ path: '/telRecharge', query: { userid: this.userid, chatid: this.chatid }})
          })
          .catch(() => {
            // on cancel
          })

        return false
      }
      this.buttonText = '钱包提交中',
      this.disabled = true
      if (this.params.type === '3') {
        this.params.nums = '1'
        this.params.tobotid = this.$route.query.botid
      } else {
        this.params.nums = this.bagNum
        this.params.tobotid = ''
      }
      this.params.moneys = this.totalAmount
      // this.params.medialink = '' // 红包封面
      this.params.remark = this.bless || '恭喜发财，大吉大利'
      this.params.anonymous = this.isNameLess ? '1' : '0'
      this.params.gettype = String(this.tagColor)
      // this.params.suid = this.$route.query.suid
      this.params.suid = this.userid
      this.params.chatid = this.chatid
      const paramString = '?type=' + this.params.type + '&nums=' + this.params.nums + '&tobotid=' + this.params.tobotid + '&moneys=' + this.params.moneys + '&medialink=' + this.params.medialink + '&remark=' + this.params.remark + '&anonymous=' + this.params.anonymous + '&gettype=' + this.params.gettype + '&suid=' + this.params.suid + '&chatid=' + this.params.chatid
      fetch(process.env.VUE_APP_BASE_API + '/yule/saveRedpack' + paramString, {
        method: 'POST'
      }).then(res => res.json())
        .then(data => {
          if (data.status == '1') {
            this.$toast.success('发送成功')
            this.buttonText = '塞钱进钱包',
            this.disabled = false
            if (!this.$route.query.test) {
              Telegram.WebApp.close()
            }
          } else {
            this.$toast(data.msg)
            this.buttonText = '塞钱进钱包',
            this.disabled = false
          }
        })
    },
    selectedNameChange(name) {
      this.title = '专属红包'
      this.recipient = name
    },
    goList() {
      this.$router.push({ path: '/peopleList', query: { userid: this.userid, chatid: this.chatid }})
    },
    afterRead(file) {
      console.log(file)
      var formData = new FormData()
      formData.append('imgfile', file.file)
      fetch(process.env.VUE_APP_BASE_API + '/yule/redpackimg', {
        method: 'POST',
        body: formData
      }).then(res => res.json())
        .then(data => {
          this.uploader = [{ url: 'http://img.rr888.vip/img/yl-hbmrtb.png', deletable: false }, { url: data.imgsrc }]
          this.clickPreview(file, data.imgsrc)
        })
    },
    onSelect(action) {
      // this.title = action.text
      this.title = this.actions.find(ele => ele.type == action.type).text
      this.params.type = action.type
      switch (action.type) {
        case '2':
          this.totalAmountName = '总金额'
          this.showBagNum = true
          // this.params.type = '2'
          break
        case '1':
          this.totalAmountName = '单个金额'
          this.showBagNum = true
          // this.params.type = '1'
          break
        case '3':
          this.totalAmountName = '金额'
          this.showBagNum = false
          // this.params.type = '3'
          break
        case '4':
          this.$router.push({ path: '/talkAdventure', query: { type: '4', test: '1' }})
          break
      }
    },
    onChoose(id) {
      this.tagColor = id
    },
    onSubmit() {
    }
  }

}
</script>
<style lang="less" scoped>
::v-deep .van-checkbox__icon--checked .van-icon{
  background: #20BB3C;
  border-color: #20BB3C;
}
::v-deep .van-field__control::-webkit-input-placeholder {
  text-align:right;
  margin-right: 10px;
}
::v-deep .van-cell{
  margin: 20px auto;
  width: 95%;
}
::v-deep .van-cell .filed-label{
  font-weight: 600;
}
::v-deep .van-field__button{
    margin-right:10px;
}
::v-deep .van-form .peopleNum{
    margin-left: 50px;
    width: 500px;
    height: 36px;
    line-height: 34px;
    color: rgba(167,165,165,1);
    font-size: 24px;
    text-align: left;
    font-family: PingFangSC-regular;
}
.sendBag{
    min-height: 100vh;
    width:100%;
    background-color: #f5f5f5;
    .sexTab{
        display: flex;
        width: 460px;
        height: 32px;
        line-height: 32px;
        .tab{
            padding: 0 20px;
        }
        .tab:not(:last-child){
            border-right: 1px solid #BBBBBB;
        }
        .tab-click{
            padding: 0 20px;
            color: #20BB3C;
        }
        .tab-click:not(:last-child){
            border-right: 1px solid #BBBBBB;
        }
    }
    .tips{
        color: rgba(167,165,165,1);
        text-align: center;
        font-size: 20px;
    }
    .money{
        height: 100px;
        width: 100%;
        margin: auto;
        font-size: 30px;
        line-height: 120px;
        font-weight: 550;
        display: flex;
        text-align: center;
        justify-content:center;
        div{
            line-height: 100px;
            font-size: 70px;
            margin-right: 20px;
        }

    }
    .emoji{
        width: 48px;
        height: 48px;
        background-image: url(~@/assets/tel/emoji.png);
        background-position: 0% 0%;
        background-size: 100% 100%;
        background-repeat: no-repeat;
        margin-right: 10px;
    }
    .usdt-icon{
        width: 48px;
        height: 48px;
        background-image: url(~@/assets/tel/USDT.png);
        background-position: 0% 0%;
        background-size: 100% 100%;
        background-repeat: no-repeat;
        margin-right: 10px;
    }
    .redBag{
        width: 48px;
        height: 48px;
        background-image: url(~@/assets/tel/redBag.png);
        background-position: 0% 0%;
        background-size: 100% 100%;
        background-repeat: no-repeat;
        margin-right: 10px;
    }
    .button{
        display: block;
        height: 75px;
        width: 335px;
        border-radius: 16px;
        margin: 20px auto;

    }
    .content{
        padding: 36px 52px 20px 52px;
         .title{
        height: 48px;
        width: 100%;
        color: #E3A11F;
        font-size: 32px;
        font-family: PingFangSC-regular;
        }
    }

}
</style>
